/** The four Working Context projections that may be restored. */
export type ContextPressureRecoverySectionName =
  | "goals"
  | "openWork"
  | "dependencies"
  | "recentEvidence";

export type ContextPressureRecoverySectionMap = Record<
  ContextPressureRecoverySectionName,
  readonly unknown[]
>;

export interface ContextPressureRecoveryOptions {
  /** Maximum number of restored items across all sections. Defaults to 32. */
  maxItems?: number;
  /** Maximum handoff-chain depth accepted by the snapshot. Defaults to 8. */
  maxDepth?: number;
}

export interface ContextPressureRecoveryDropped {
  section: ContextPressureRecoverySectionName;
  count: number;
}

export interface ContextPressureRecoveryResult {
  status: "recovered" | "unknown" | "depth-exceeded";
  complete: false;
  truncated: boolean;
  kept: number;
  dropped: number;
  droppedBySection: ContextPressureRecoveryDropped[];
  digest: string;
  sections?: ContextPressureRecoverySectionMap;
  error?: "snapshot-missing" | "snapshot-empty" | "depth-exceeded";
  observedDepth?: number;
  maxDepth?: number;
}

interface HandoffLike {
  depth?: number;
  chain?: readonly unknown[];
  history?: readonly unknown[];
}

interface WorkingContextLike {
  goals?: readonly unknown[];
  openWork?: readonly unknown[];
  dependencies?: readonly unknown[];
  recentEvidence?: readonly unknown[];
  handoff?: HandoffLike;
  handoffChain?: readonly unknown[];
  handoffDepth?: number;
}

const SECTION_NAMES: readonly ContextPressureRecoverySectionName[] = [
  "goals",
  "openWork",
  "dependencies",
  "recentEvidence",
];

function canonicalize(value: unknown): unknown {
  if (value === null || typeof value !== "object") {
    return typeof value === "number" && !Number.isFinite(value)
      ? String(value)
      : value;
  }
  if (Array.isArray(value)) {
    return value.map(canonicalize);
  }
  const record = value as Record<string, unknown>;
  const result: Record<string, unknown> = {};
  for (const key of Object.keys(record).sort()) {
    if (record[key] !== undefined) {
      result[key] = canonicalize(record[key]);
    }
  }
  return result;
}

function digestOf(value: unknown): string {
  return createHash("sha256")
    .update(JSON.stringify(canonicalize(value)))
    .digest("hex");
}

function asArray(value: unknown): readonly unknown[] | undefined {
  return Array.isArray(value) ? value : undefined;
}

function snapshotSections(snapshot: WorkingContextLike): ContextPressureRecoverySectionMap | undefined {
  const goals = asArray(snapshot.goals);
  const openWork = asArray(snapshot.openWork);
  const dependencies = asArray(snapshot.dependencies);
  const recentEvidence = asArray(snapshot.recentEvidence);
  if (
    goals === undefined ||
    openWork === undefined ||
    dependencies === undefined ||
    recentEvidence === undefined
  ) {
    return undefined;
  }
  return { goals, openWork, dependencies, recentEvidence };
}

function observedDepth(snapshot: WorkingContextLike): number | undefined {
  if (Number.isInteger(snapshot.handoffDepth) && (snapshot.handoffDepth as number) >= 0) {
    return snapshot.handoffDepth;
  }
  const handoff = snapshot.handoff;
  if (Number.isInteger(handoff?.depth) && (handoff?.depth as number) >= 0) {
    return handoff?.depth;
  }
  const chain = snapshot.handoffChain ?? handoff?.chain ?? handoff?.history;
  if (Array.isArray(chain)) {
    return Math.max(0, chain.length - 1);
  }
  return undefined;
}

function baseResult(): ContextPressureRecoveryResult {
  return {
    status: "unknown",
    complete: false,
    truncated: false,
    kept: 0,
    dropped: 0,
    droppedBySection: [],
    digest: digestOf({
      status: "unknown",
      complete: false,
      sections: null,
      kept: 0,
      dropped: 0,
    }),
  };
}

/**
 * Projects a bounded, deterministic recovery summary from a Working Context
 * snapshot. The function never follows a handoff chain and never reports that
 * the underlying task is complete.
 */
export function recoverContextPressure(
  snapshot: WorkingContextLike | null | undefined,
  options: ContextPressureRecoveryOptions = {},
): ContextPressureRecoveryResult {
  const maxItems = options.maxItems ?? 32;
  const maxDepth = options.maxDepth ?? 8;
  if (!Number.isSafeInteger(maxItems) || maxItems < 0) {
    throw new RangeError("maxItems must be a non-negative safe integer");
  }
  if (!Number.isSafeInteger(maxDepth) || maxDepth < 0) {
    throw new RangeError("maxDepth must be a non-negative safe integer");
  }

  if (snapshot === null || snapshot === undefined) {
    const result = baseResult();
    result.error = "snapshot-missing";
    result.digest = digestOf({
      status: result.status,
      complete: false,
      error: result.error,
      sections: null,
    });
    return result;
  }

  const depth = observedDepth(snapshot);
  if (depth !== undefined && depth > maxDepth) {
    const result = baseResult();
    result.status = "depth-exceeded";
    result.error = "depth-exceeded";
    result.observedDepth = depth;
    result.maxDepth = maxDepth;
    result.digest = digestOf({
      status: result.status,
      complete: false,
      error: result.error,
      observedDepth: depth,
      maxDepth,
      sections: null,
    });
    return result;
  }

  const source = snapshotSections(snapshot);
  if (source === undefined) {
    const result = baseResult();
    result.error = "snapshot-empty";
    result.digest = digestOf({
      status: result.status,
      complete: false,
      error: result.error,
      sections: null,
    });
    return result;
  }

  const total = SECTION_NAMES.reduce((count, name) => count + source[name].length, 0);
  if (total === 0) {
    const result = baseResult();
    result.error = "snapshot-empty";
    result.digest = digestOf({
      status: result.status,
      complete: false,
      error: result.error,
      sections: null,
    });
    return result;
  }

  let remaining = maxItems;
  const sections = {} as {
    [K in ContextPressureRecoverySectionName]: unknown[];
  };
  const droppedBySection: ContextPressureRecoveryDropped[] = [];
  let kept = 0;
  let dropped = 0;

  for (const name of SECTION_NAMES) {
    const items = source[name];
    const take = Math.min(items.length, remaining);
    sections[name] = items.slice(0, take);
    const omitted = items.length - take;
    kept += take;
    dropped += omitted;
    remaining -= take;
    if (omitted > 0) {
      droppedBySection.push({ section: name, count: omitted });
    }
  }

  const truncated = dropped > 0;
  const result: ContextPressureRecoveryResult = {
    status: "recovered",
    complete: false,
    truncated,
    kept,
    dropped,
    droppedBySection,
    digest: "",
    sections,
  };
  result.digest = digestOf({
    status: result.status,
    complete: false,
    truncated,
    kept,
    dropped,
    droppedBySection,
    sections,
  });
  return result;
}

export const recoverWorkingContext = recoverContextPressure;
