interface HandoffLike {
  depth?: number;
  chain?: readonly unknown[];
  history?: readonly unknown[];
}

interface WorkingContextLike {
  goals?: readonly unknown[];
  openWork?: readonly unknown[];
  dependencies?: readonly unknown[];
  recentEvidence?: readonly unknown[];
  handoff?: HandoffLike;
  handoffChain?: readonly unknown[];
  handoffDepth?: number;
}

const SECTION_NAMES: readonly ContextPressureRecoverySectionName[] = [
  "goals",
  "openWork",
  "dependencies",
  "recentEvidence",
];

function canonicalize(value: unknown): unknown {
  if (value === null || typeof value !== "object") {
    return typeof value === "number" && !Number.isFinite(value)
      ? String(value)
      : value;
  }
  if (Array.isArray(value)) {
    return value.map(canonicalize);
  }
  const record = value as Record<string, unknown>;
  const result: Record<string, unknown> = {};
  for (const key of Object.keys(record).sort()) {
    if (record[key] !== undefined) {
      result[key] = canonicalize(record[key]);
    }
  }
  return result;
}

function digestOf(value: unknown): string {
  return createHash("sha256")
    .update(JSON.stringify(canonicalize(value)))
    .digest("hex");
}

function asArray(value: unknown): readonly unknown[] | undefined {
  return Array.isArray(value) ? value : undefined;
}

function snapshotSections(snapshot: WorkingContextLike): ContextPressureRecoverySectionMap | undefined {
